package guard

import (
	"bytes"
	"errors"
	"fmt"
	"go/ast"
	"go/format"
	"go/token"
	"path"
	"sort"
	"strconv"
	"strings"
	"unicode"
)

// GenFile is the generated addon list in an addons directory.
const GenFile = "addons_gen.go"

// DocFile holds an addons package's comment and its //go:generate line.
const DocFile = "doc.go"

// genHeaderPrefix starts the first line of a generated list. The line ends with
// "; DO NOT EDIT." so Go tools treat the file as generated.
const genHeaderPrefix = "// Code generated by dashygotui gen -state "

// libraryPath is the import path of the library.
const libraryPath = "github.com/CeeSmag/dashygotui"

// addonVar is one top-level variable of an addon file: an addon.
type addonVar struct {
	file string // base name, such as opt_backup.go
	line int
	name string
}

// IsAddonFile reports whether rel is an addon file by name (opt_*.go and the
// rest), as opposed to the package's doc.go or generated list.
func IsAddonFile(rel string) bool {
	return addonFileName.MatchString(path.Base(rel)) && !strings.HasSuffix(rel, "_test.go")
}

// isSupportFile reports whether rel is one of the two files of an addons
// package that are not addons: doc.go and the generated list.
func isSupportFile(rel string) bool {
	b := path.Base(rel)
	return b == GenFile || b == DocFile
}

// addonVars lists the top-level variables of the addon files among files,
// sorted by file and line.
func addonVars(files []Source) []addonVar {
	var out []addonVar
	for _, s := range files {
		if !IsAddonFile(s.Rel) {
			continue
		}
		for _, d := range s.File.Decls {
			gd, ok := d.(*ast.GenDecl)
			if !ok || gd.Tok != token.VAR {
				continue
			}
			for _, spec := range gd.Specs {
				for _, id := range spec.(*ast.ValueSpec).Names {
					if id.Name != "_" {
						out = append(out, addonVar{file: path.Base(s.Rel), line: s.Line(id.Pos()), name: id.Name})
					}
				}
			}
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].file != out[j].file {
			return out[i].file < out[j].file
		}
		return out[i].line < out[j].line
	})
	return out
}

// splitState splits "import/path.Type" into the import path, the package
// alias the generated file uses, and the type name.
func splitState(state string) (imp, alias, typ string, err error) {
	i := strings.LastIndex(state, ".")
	if i <= 0 || i == len(state)-1 || strings.HasSuffix(state[:i], "/") {
		return "", "", "", fmt.Errorf("-state %q: want <import path>.<Type>, such as example.com/app/dashboard.State", state)
	}
	imp, typ = state[:i], state[i+1:]
	if !token.IsIdentifier(typ) || !token.IsExported(typ) {
		return "", "", "", fmt.Errorf("-state %q: %q is not an exported type name", state, typ)
	}
	parts := strings.Split(imp, "/")
	alias = parts[len(parts)-1]
	if len(parts) > 1 && majorVersion.MatchString(alias) {
		alias = parts[len(parts)-2]
	}
	alias = strings.Map(func(r rune) rune {
		if unicode.IsLetter(r) || unicode.IsDigit(r) || r == '_' {
			return r
		}
		return '_'
	}, alias)
	if alias == "" || !token.IsIdentifier(alias) || alias == "dashygotui" {
		alias = "app"
	}
	return imp, alias, typ, nil
}

// AddonList returns the generated addons_gen.go for one addons package: a
// function All listing every top-level variable of its addon files, each
// wrapped in dashygotui.At with the place it is declared. files are the
// package's parsed non-test sources; the generated file among them is ignored.
// state names the application's state type as "import/path.Type".
func AddonList(files []Source, state string) ([]byte, error) {
	imp, alias, typ, err := splitState(state)
	if err != nil {
		return nil, err
	}
	pkg := ""
	for _, s := range files {
		if path.Base(s.Rel) == GenFile {
			continue
		}
		if pkg == "" {
			pkg = s.File.Name.Name
		} else if s.File.Name.Name != pkg {
			return nil, fmt.Errorf("the directory holds packages %s and %s", pkg, s.File.Name.Name)
		}
	}
	if pkg == "" {
		return nil, errors.New("no Go files besides the generated list, so the package name is unknown (add doc.go)")
	}
	s := alias + "." + typ
	var b bytes.Buffer
	fmt.Fprintf(&b, "%s%s; DO NOT EDIT.\n\npackage %s\n\n", genHeaderPrefix, state, pkg)
	fmt.Fprintf(&b, "import (\n\t%q\n\n\t%s %q\n)\n\n", libraryPath, alias, imp)
	b.WriteString("// All returns every addon declared in this package, in file order, each with\n" +
		"// the place it is declared. Pass it to the dashboard in Config.Addons.\n")
	fmt.Fprintf(&b, "func All() []dashygotui.Addon[%s] {\n\treturn []dashygotui.Addon[%s]{\n", s, s)
	for _, v := range addonVars(files) {
		fmt.Fprintf(&b, "\t\tdashygotui.At[%s](%s, %s),\n", s, strconv.Quote(fmt.Sprintf("%s:%d", v.file, v.line)), v.name)
	}
	b.WriteString("\t}\n}\n")
	out, err := format.Source(b.Bytes())
	if err != nil {
		return nil, fmt.Errorf("formatting the generated list: %w", err)
	}
	return out, nil
}

// GenState returns the -state a generated list was written with, read from its
// first line, and whether f is such a list.
func GenState(f *ast.File) (string, bool) {
	for _, cg := range f.Comments {
		if cg.Pos() > f.Package {
			break
		}
		for _, c := range cg.List {
			if rest, ok := strings.CutPrefix(c.Text, genHeaderPrefix); ok {
				if state, ok := strings.CutSuffix(rest, "; DO NOT EDIT."); ok {
					return state, true
				}
			}
		}
	}
	return "", false
}
